let leadership={frames:{}};
let yearlyReigns={sources:{},reigns:[]},yearlyStories={sources:{},stories:[]};
function leaderInfo(feature,frame=frames[index]){const record=leadership.frames[frame.id]?.[feature.properties.title];if(record)return {...record,displayTitle:feature.properties.displayTitle||feature.properties.title};return {rulers:[],powerHolders:[],changes:[],note:'本年负责人尚未核实。',status:'待核',short:'负责人待核',sources:[],referenceYear:frame.year,basis:'unresolved',search:''};}
function leaderHtml(feature){const e=leaderInfo(feature);const row=(r)=>'<div class="leader-person"><strong>'+r.name+'</strong><span>'+r.title+'</span>'+(r.note&&!r.note.startsWith('依据历史纪年索引')?'<p>'+r.note+'</p>':'')+'</div>';return '<section class="leader-info"><div class="leader-head"><h4>领导人与实际权力</h4><span class="leader-status">'+e.status+'</span></div><div class="leader-year">'+(e.basis==='later_in_slice'?'人物对应：':'代表年份：')+yr(e.referenceYear)+'</div>'+(e.rulers.length?'<h5>君主／首领／当地负责人</h5>'+e.rulers.map(row).join(''):'<p>尚未可靠确认当年直接负责人。</p>')+(e.powerHolders.length?'<h5>实权、摄政或重要军政人物</h5>'+e.powerHolders.map(row).join(''):'')+(e.note?'<p class="leader-context">'+e.note+'</p>':'')+(e.changes.length?'<details class="leader-changes"><summary>本切片后续人物（已整理 '+e.changes.length+' 条）</summary><p>以下按纪年索引或阶段资料排列，可能跨越多次更替；并非均在代表年掌权，也不是精确到月日的完整在位表。</p><ul>'+e.changes.map(r=>'<li><b>'+r.name+'</b> · '+r.title+'</li>').join('')+'</ul></details>':'')+(e.sources.length?'<div class="ethnicity-sources">'+e.sources.map((u,i)=>'<a href="'+u+'" target="_blank" rel="noopener">人物资料 '+(i+1)+' ↗</a>').join(' · ')+'</div>':'')+'<p class="leader-disclaimer">在位君主、实际掌权者、重要将领是不同身份；人物资料仍需持续校核。</p></section>';}
let cityNames={entries:{},sources:{},extra:[]};
let ethnicities={};
let chronicleContext={sources:{},groups:[]};
function ethnicInfo(feature,frame=frames[index]){const name=feature.properties.title;const e=ethnicities[name];if(name==='吴'&&frame?.year>=902&&frame?.year<=937&&e)return {...e,clan:'杨氏君主；徐氏逐渐掌权',note:'此处为五代十国的杨吴，与三国孙氏所建的孙吴无关。君主与实际权力分别列示。',sources:['https://zh.wikisource.org/wiki/新五代史/卷61']};if(name==="宋"&&e)return {...e,clan:frame?.group==="北宋"?"赵氏皇室；宋太祖赵匡胤建立":"刘宋刘氏皇室；刘裕建立"};if(name==="齐"&&e)return {...e,clan:frame?.group==="南北朝"?"南齐萧氏；萧道成建立":"楚汉之际齐地诸侯集团"};if(!e)return {label:"待补充",short:"待补充",clan:"尚未完成归类",note:"需要进一步核对史料。",sources:[],status:"待考"};if(name==="北凉"&&frame?.year<401)return {...e,label:"汉（段业）＋卢水胡（沮渠氏）",short:"汉／卢水胡",note:"此代表年份由汉人段业居君主之位，卢水胡沮渠氏参与掌权；401年后沮渠蒙逊取代段业。"+e.note};return e;}
let frames=[],land,rivers,index=0,cursorYear=-221,selected=null,timer=null,projection,path,zoom,svg,root,width,height;
